css:
.pattern {
  width: 100%;
  height: 100%;

  background:
    conic-gradient(
        transparent 25%,
        hsl(270, 60%, 65%) 0 50%,
        transparent 0 75%,
        #000 0
      )
      0 / 4em 4em,
    repeating-conic-gradient(hsl(270, 60%, 65%) 0 25%, #000 0 50%) 0 / 0.5em
      0.5em;

  animation: hueShift 20s linear infinite;
}

@keyframes hueShift {
  from {
    filter: hue-rotate(0deg);
  }
  to {
    filter: hue-rotate(360deg);
  }
}
